**Recommended Fix:**
```javascript
// Load from secure database or environment-based configuration
const getUsers = async () => {
  // Use a real database connection
  const users = await db.query('SELECT id, name FROM users');
  return users;
};

app.get('/users', authenticateToken, async (req, res) => {
  try {
    const users = await getUsers();
    // Never expose sensitive fields like emails without permission checks
    const sanitizedUsers = users.map(u => ({ id: u.id, name: u.name }));
    res.json(sanitizedUsers);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});
```

